  const b=xp(); try{ await bot.attack(t); }catch(e){ console.log("e",e?.message); }
  const w=Date.now()+20000;
  while(Date.now()<w){ const s2=sdk.getState();
    const cur=s2.nearbyNpcs.find(n=>n.uid===t.uid||(n.name===t.name&&n.distance<3));
    if(!s2.player?.combat?.inCombat && xp()>b) break;
